package Controllers; import Services.CartService; import java.io.*; import javax.servlet.*; import javax.servlet.http.*;
public class ViewProductServlet extends HttpServlet{private final CartService service=new CartService();protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{r.setAttribute("products",service.products());r.getRequestDispatcher("HomeView.jsp").forward(r,p);}}
